import{_ as t,o as a,c as s,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const u=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/1-getting-started.md","filePath":"guide/1-getting-started.md"}'),r={name:"guide/1-getting-started.md"};function l(o,e,n,p,d,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>Welcome to the <strong>Rullst</strong> Getting Started guide!</p><p>Rullst is a blazing-fast, strictly-typed Full-Stack web framework designed to give you a pristine developer experience while prioritizing security and zero-allocation performance.</p><h2 id="_1-installation" tabindex="-1">1. Installation <a class="header-anchor" href="#_1-installation" aria-label="Permalink to &quot;1. Installation&quot;">​</a></h2><p>First, ensure you have Rust installed. The official and recommended way is to visit <a href="https://rustup.rs/" target="_blank" rel="noreferrer">rustup.rs</a>.</p><p><strong>For macOS and Linux:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --proto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;=https&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tlsv1.2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sSf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://sh.rustup.rs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p><strong>For Windows:</strong> Download and run <code>rustup-init.exe</code> from the website.</p><p>Next, install the <strong>Rullst CLI</strong>. The CLI is the heart of the developer experience, handling scaffolding, static sites (RullstPress), database migrations, and more.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cargo-rullst</span></span></code></pre></div><h2 id="_2-creating-your-first-project" tabindex="-1">2. Creating Your First Project <a class="header-anchor" href="#_2-creating-your-first-project" aria-label="Permalink to &quot;2. Creating Your First Project&quot;">​</a></h2><p>We have completely redesigned the project creation experience. Instead of remembering complex flags, just run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rullst</span></span></code></pre></div><p>The <strong>Rullst App Creator</strong> will launch an interactive wizard. Let&#39;s create a beautiful Portfolio:</p><ol><li>Select <strong>Create New App</strong>.</li><li><strong>App Name</strong>: Provide a simple lowercase name (e.g., <code>my_portfolio</code>).</li><li><strong>Starter Blueprint</strong>: Choose <strong>Portfolio 🔥 (showcase for Rullst/AI developers) - HOT</strong>.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_portfolio</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rullst</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>The <code>cargo rullst dev</code> command automatically compiles your code and spins up a local server. If you edit any <code>.rs</code> file, it will instantly recompile using Hot Reload!</p></div><h2 id="_3-rullst-blueprints-showcase" tabindex="-1">3. Rullst Blueprints Showcase <a class="header-anchor" href="#_3-rullst-blueprints-showcase" aria-label="Permalink to &quot;3. Rullst Blueprints Showcase&quot;">​</a></h2><p>The Rullst framework accelerates your development by providing <strong>Blueprints</strong>. A Blueprint is a highly-polished, pre-built application template that serves as the foundation for your project.</p><p>When you run <code>cargo rullst</code>, the wizard will ask you to select a Blueprint. All Blueprints feature the official Rullst color scheme (Emerald Green and Orange) and are built with zero-allocation HTML macros and HTMX.</p><h2 id="_1-blank-starter" tabindex="-1">1. Blank Starter <a class="header-anchor" href="#_1-blank-starter" aria-label="Permalink to &quot;1. Blank Starter&quot;">​</a></h2><p><strong>Use Case:</strong> Custom, from-scratch development. This is the minimal template. It includes a simple HTMX reactive counter to demonstrate the frontend-backend communication, but leaves the rest entirely up to you.</p><h2 id="_2-portfolio-🔥" tabindex="-1">2. Portfolio 🔥 <a class="header-anchor" href="#_2-portfolio-🔥" aria-label="Permalink to &quot;2. Portfolio 🔥&quot;">​</a></h2><p><strong>Use Case:</strong> Developer showcases and personal branding. <strong>Status:</strong> HOT! A visually stunning, glassmorphic portfolio template designed specifically for Rullst/AI developers. It includes:</p><ul><li>A responsive Hero section with glowing text.</li><li>Project cards with hover animations.</li><li>A built-in contact form.</li></ul><h2 id="_3-lms-platform" tabindex="-1">3. LMS Platform <a class="header-anchor" href="#_3-lms-platform" aria-label="Permalink to &quot;3. LMS Platform&quot;">​</a></h2><p><strong>Use Case:</strong> Online course platforms and video streaming. A complete learning management system featuring:</p><ul><li>Courses and Lessons database models.</li><li>Migrations pre-populated with seed data.</li><li>A glassmorphic video player layout integrated with HTMX.</li></ul><h2 id="_4-saas-app-starter" tabindex="-1">4. SaaS App Starter <a class="header-anchor" href="#_4-saas-app-starter" aria-label="Permalink to &quot;4. SaaS App Starter&quot;">​</a></h2><p><strong>Use Case:</strong> Subscription-based products and billing. The ultimate boilerplate for SaaS products, pre-wired with:</p><ul><li>User authentication (login, signup, session management).</li><li>Stripe pricing panels and subscription checkout views.</li><li>Secure user dashboard.</li></ul><h2 id="_5-blog-press" tabindex="-1">5. Blog / Press <a class="header-anchor" href="#_5-blog-press" aria-label="Permalink to &quot;5. Blog / Press&quot;">​</a></h2><p><strong>Use Case:</strong> Content creation and articles. A static site generator pre-wired with Nexus CMS. It features:</p><ul><li>A beautiful article reading view with typography optimized for readability.</li><li>A fully functional Markdown parser engine.</li><li>SEO-friendly metadata injection.</li></ul><h2 id="_6-uptime-monitor" tabindex="-1">6. Uptime Monitor <a class="header-anchor" href="#_6-uptime-monitor" aria-label="Permalink to &quot;6. Uptime Monitor&quot;">​</a></h2><p><strong>Use Case:</strong> Infrastructure tracking and observability. A robust system designed to ping URLs and track their health. It features:</p><ul><li>A dashboard with live status indicators.</li><li>A background worker (<code>rullst::runtime::spawn</code>) that loops every minute to check endpoints.</li><li><em>Note: Background workers include a startup delay to ensure the database pool is fully initialized before querying.</em></li></ul><h2 id="_7-erp-pocket" tabindex="-1">7. ERP Pocket <a class="header-anchor" href="#_7-erp-pocket" aria-label="Permalink to &quot;7. ERP Pocket&quot;">​</a></h2><p><strong>Use Case:</strong> Business management, stock, and inventory tracking. A complete back-office suite out of the box. It features:</p><ul><li>A complex relational database schema (Products and Orders).</li><li>Full CRUD operations with HTMX.</li><li>A sleek, split-pane dashboard for simultaneous product listing and order creation.</li></ul><hr><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Blueprint Evolution:</strong> We are constantly refining our Blueprints. In version 2.0.1, all Blueprints were rigorously audited to ensure 100% macro syntax compliance (<code>routes!</code> and <code>html!</code>) and perfect database initialization order. You can build upon them with absolute confidence.</p></div>`,42)])])}const g=t(r,[["render",l]]);export{u as __pageData,g as default};
